// Package upstream standalone renderers as inert strings for isolated artifacts.
// No CDN, dynamic import, Node runtime, or DeepTutor application frontend.
const fs = require('node:fs');
const path = require('node:path');
const root = path.join(__dirname, '..');
for (const [name, file, license] of [
  ['mermaid', 'mermaid/dist/mermaid.min.js', 'mermaid/LICENSE'],
  ['chart', 'chart.js/dist/chart.umd.min.js', 'chart.js/LICENSE.md'],
]) {
  const source = fs.readFileSync(path.join(root, 'node_modules', file), 'utf8').replace(/\/\/# sourceMappingURL=[^\n]*/g, '');
  fs.writeFileSync(path.join(root, `src/features/${name}-runtime.ts`), `// Generated by scripts/bundle-diagrams.cjs; see ${name}-LICENSE.txt.\nexport default ${JSON.stringify(source)};\n`);
  fs.copyFileSync(path.join(root, 'node_modules', license), path.join(root, `src/features/${name}-LICENSE.txt`));
  console.log(`Bundled ${name}: ${source.length} characters`);
}
